        private static void OpenProjection(Window owner, DeepSystemsContext ctx, WorldIndex index, string sourceKind, string sourceId, string fingerprint, Func<CyberTwinModel> factory)
        {
            Load(ctx); List<CyberTwinModel> existing = Store.Twins.Where(x => Eq(x.SourceKind, sourceKind) && Eq(x.SourceId, sourceId)).OrderByDescending(x => x.UpdatedUtc ?? x.CreatedUtc).ToList(); CyberTwinModel exact = existing.FirstOrDefault(x => Eq(x.SourceFingerprint, fingerprint)); if (exact != null) { OpenTwin(owner, ctx, index, exact); return; }
            if (existing.Count > 0)
            {
                MessageBoxResult drift = MessageBox.Show(owner, "The source fingerprint has changed since the latest projection.\n\nYES · create a traceable child revision\nNO · open the historical projection\nCANCEL · leave unchanged", "YOMI · SOURCE DRIFT BOUNDARY", MessageBoxButton.YesNoCancel, MessageBoxImage.Warning); if (drift == MessageBoxResult.No) { OpenTwin(owner, ctx, index, existing[0]); return; } if (drift != MessageBoxResult.Yes) return;
            }
            CyberTwinModel twin = factory == null ? StarterTwin("Untitled digital twin", "Declared cybernetic abstraction.") : factory(); if (twin == null) return; twin.Id = Id("twin"); twin.ParentTwinId = existing.Count == 0 ? null : existing[0].Id; twin.SourceKind = sourceKind; twin.SourceId = sourceId; twin.SourceFingerprint = fingerprint; twin.CreatedUtc = Now(); twin.UpdatedUtc = twin.CreatedUtc; twin.Revision = existing.Count == 0 ? 1 : Math.Max(1, existing[0].Revision) + 1; Store.Twins.Insert(0, twin); Save(ctx); AppendLedger(ctx, "TWIN_PROJECTED", twin.Id, sourceKind + ":" + sourceId + (existing.Count == 0 ? "" : " · source drift child of " + existing[0].Id), CyberneticsKernel.Fingerprint(twin), ""); OpenTwin(owner, ctx, index, twin);
        }

