        private static CyberTwinModel ProjectEngineering(EngineeringArchitecture architecture)
        {
            List<EngineeringComponent> components = (architecture.Components ?? new List<EngineeringComponent>()).Where(x => Active(x.Status)).Take(32).ToList(); if (components.Count == 0) return StarterTwin("Engineering twin · " + (architecture.Name ?? "Architecture"), architecture.Charter);
            CyberTwinModel t = NewProjected("Engineering twin · " + (architecture.Name ?? "Architecture"), "Linear reliability/capacity projection of a systems-engineering architecture. Component and interface declarations become a design abstraction only."); Dictionary<string, int> map = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase); for (int i = 0; i < components.Count; i++) { EngineeringComponent component = components[i]; map[component.Id] = i; double rateSum = Math.Max(0, component.FailureRatePerHour) + Math.Max(0, component.RepairRatePerHour), declaredAvailability = rateSum > 0 ? Math.Max(0, component.RepairRatePerHour) / rateSum : 0.95, initial = Math.Max(0.05, Math.Min(1, declaredAvailability)); t.States.Add(X("component-" + component.Id, component.Name, "availability", initial, 0, 1, Math.Max(1e-8, component.FailureRatePerHour), Math.Max(0.1, component.Capacity))); t.States[i].EvidenceNodeIds.AddRange(component.EvidenceNodeIds ?? new List<string>()); }
            double[][] a = Z(components.Count, components.Count); for (int i = 0; i < components.Count; i++) a[i][i] = Math.Max(0.70, Math.Min(0.9999, 1 - Math.Max(0, components[i].FailureRatePerHour) * Math.Max(1, t.SamplePeriod))); foreach (EngineeringInterface edge in (architecture.Interfaces ?? new List<EngineeringInterface>()).Where(x => Active(x.Status))) { int from, to; if (!map.TryGetValue(edge.FromComponentId ?? "", out from) || !map.TryGetValue(edge.ToComponentId ?? "", out to)) continue; a[to][from] += Math.Min(0.06, 0.005 + Math.Abs(edge.Capacity) / (10000 + Math.Abs(edge.Capacity))); a[to][to] = Math.Max(0.60, a[to][to] - 0.005); } t.A = a;
            List<EngineeringComponent> controlComponents = components.Where(x => Eq(x.Kind, "CONTROL") || Eq(x.Kind, "BOUNDARY")).Take(8).ToList(); if (controlComponents.Count == 0) controlComponents.Add(components[0]); t.B = Z(components.Count, controlComponents.Count); for (int j = 0; j < controlComponents.Count; j++) { int i = map[controlComponents[j].Id]; t.Inputs.Add(U("control-" + controlComponents[j].Id, "Allocation · " + controlComponents[j].Name, "normalized", -0.2, 0.2, -0.04, 0.04, 0.2)); t.B[i][j] = 0.08; }
            List<EngineeringComponent> observed = components.Take(16).ToList(); t.C = Z(observed.Count, components.Count); t.D = Z(observed.Count, controlComponents.Count); for (int i = 0; i < observed.Count; i++) { int state = map[observed[i].Id]; t.Outputs.Add(Y("observe-" + observed[i].Id, "Observed · " + observed[i].Name, "availability", t.States[state].InitialValue, 0, 1, 0.0025, 1, 1)); t.C[i][state] = 1; }
            foreach (EngineeringFailureMode failure in (architecture.FailureModes ?? new List<EngineeringFailureMode>()).Where(x => Active(x.Status)).Take(MaxFaults)) { CyberFaultSignature f = new CyberFaultSignature { Id = "engineering-" + failure.Id, Name = failure.Name, Description = failure.Cause + " · " + failure.Effect, PriorWeight = Math.Max(1e-6, failure.Probability) }; foreach (CyberMeasuredOutput y in t.Outputs) { f.ResidualMeans[y.Id] = y.Id.EndsWith(failure.ComponentId ?? "", StringComparison.OrdinalIgnoreCase) ? -Math.Min(0.8, 0.05 + failure.Severity * 0.05) : 0; f.ResidualVariances[y.Id] = y.MeasurementNoiseVariance * 2; } f.EvidenceNodeIds.AddRange(failure.EvidenceNodeIds ?? new List<string>()); t.FaultSignatures.Add(f); } t.Assumptions.AddRange(architecture.Assumptions ?? new List<string>()); t.Assumptions.Add("Projected from engineering fingerprint " + SystemsEngineeringKernel.Fingerprint(architecture) + "; reliability and capacity coefficients require empirical calibration."); t.EvidenceNodeIds.AddRange(architecture.EvidenceNodeIds ?? new List<string>()); return t;
        }

        private static CyberTwinModel ProjectVerification(VerificationModel model)
        {
            List<VerificationState> states = (model.States ?? new List<VerificationState>()).Where(x => Active(x.Status)).Take(32).ToList(); if (states.Count == 0) return StarterTwin("Verification twin · " + (model.Name ?? "Model"), model.Description); CyberTwinModel t = NewProjected("Verification occupancy twin · " + (model.Name ?? "Model"), "Linear occupancy-flow abstraction projected from a formal transition system. It does not replace exact model checking."); Dictionary<string, int> map = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase); for (int i = 0; i < states.Count; i++) { map[states[i].Id] = i; t.States.Add(X("formal-" + states[i].Id, states[i].Name, "occupancy", (model.InitialStateIds ?? new List<string>()).Contains(states[i].Id) ? 1 : 0, 0, 1, 0.0001, 1)); t.States[i].EvidenceNodeIds.AddRange(states[i].EvidenceNodeIds ?? new List<string>()); }
            t.A = Z(states.Count, states.Count); int[] outgoing = new int[states.Count]; foreach (VerificationTransition edge in (model.Transitions ?? new List<VerificationTransition>()).Where(x => Active(x.Status))) { int from, to; if (map.TryGetValue(edge.FromStateId ?? "", out from) && map.TryGetValue(edge.ToStateId ?? "", out to)) outgoing[from]++; } for (int i = 0; i < states.Count; i++) if (outgoing[i] == 0) t.A[i][i] = 0.98; foreach (VerificationTransition edge in (model.Transitions ?? new List<VerificationTransition>()).Where(x => Active(x.Status))) { int from, to; if (map.TryGetValue(edge.FromStateId ?? "", out from) && map.TryGetValue(edge.ToStateId ?? "", out to)) t.A[to][from] += 0.98 / Math.Max(1, outgoing[from]); }
            t.Inputs.Add(U("formal-perturbation", "Declared transition perturbation", "normalized", -0.1, 0.1, -0.02, 0.02, 0.5)); t.B = Z(states.Count, 1); t.B[0][0] = 0.02; int observed = Math.Min(16, states.Count); t.C = Z(observed, states.Count); t.D = Z(observed, 1); for (int i = 0; i < observed; i++) { t.Outputs.Add(Y("formal-observe-" + states[i].Id, "Occupancy · " + states[i].Name, "occupancy", t.States[i].InitialValue, 0, 1, 0.0001, 1, 1)); t.C[i][i] = 1; } t.Assumptions.Add("Linear occupancy projection is an analytic lens; exact temporal properties remain owned by the Axiomatic Verification Reactor."); t.EvidenceNodeIds.AddRange(model.EvidenceNodeIds ?? new List<string>()); return t;
        }

        private static CyberTwinModel ProjectStrategy(StrategyModel model)
        {
            List<StrategyVariable> variables = (model.Variables ?? new List<StrategyVariable>()).Where(x => Active(x.Status)).Take(32).ToList(); if (variables.Count == 0) return StarterTwin("Strategy twin · " + (model.Name ?? "Model"), model.Charter); CyberTwinModel t = NewProjected("Strategy dynamics twin · " + (model.Name ?? "Model"), "Linear dynamic projection of a structural causal strategy model. Causal coefficients remain hypotheses and do not become actuator gains."); Dictionary<string, int> map = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase); for (int i = 0; i < variables.Count; i++) { StrategyVariable v = variables[i]; map[v.Id] = i; t.States.Add(X("strategy-" + v.Id, v.Name, v.Unit, v.Baseline, v.Minimum, v.Maximum, v.Uncertain ? 0.01 : 0.0001, 1)); t.States[i].EvidenceNodeIds.AddRange(v.EvidenceNodeIds ?? new List<string>()); } t.A = Z(variables.Count, variables.Count); for (int i = 0; i < variables.Count; i++) t.A[i][i] = 0.82; foreach (StrategyEdge edge in (model.Edges ?? new List<StrategyEdge>()).Where(x => Active(x.Status))) { int from, to; if (map.TryGetValue(edge.FromVariableId ?? "", out from) && map.TryGetValue(edge.ToVariableId ?? "", out to)) t.A[to][from] += Math.Max(-0.15, Math.Min(0.15, edge.Coefficient * 0.05)); }
            List<StrategyVariable> decisions = variables.Where(x => Eq(x.Kind, "DECISION")).Take(8).ToList(); if (decisions.Count == 0) decisions.Add(variables[0]); t.B = Z(variables.Count, decisions.Count); for (int j = 0; j < decisions.Count; j++) { int i = map[decisions[j].Id]; double span = Math.Max(1e-6, decisions[j].Maximum - decisions[j].Minimum); t.Inputs.Add(U("do-" + decisions[j].Id, "do(" + decisions[j].Name + ")", decisions[j].Unit, -span * 0.1, span * 0.1, -span * 0.02, span * 0.02, 0.2)); t.B[i][j] = 0.25; }
            List<StrategyVariable> outcomes = variables.Where(x => Eq(x.Kind, "OUTCOME")).Take(16).ToList(); if (outcomes.Count == 0) outcomes = variables.Take(16).ToList(); t.C = Z(outcomes.Count, variables.Count); t.D = Z(outcomes.Count, decisions.Count); for (int i = 0; i < outcomes.Count; i++) { int state = map[outcomes[i].Id]; t.Outputs.Add(Y("outcome-" + outcomes[i].Id, outcomes[i].Name, outcomes[i].Unit, outcomes[i].Baseline, outcomes[i].Minimum, outcomes[i].Maximum, outcomes[i].Uncertain ? 0.01 : 0.001, 1, 1)); t.C[i][state] = 1; } foreach (StrategyConstraint constraint in model.Constraints ?? new List<StrategyConstraint>()) if (Active(constraint.Status) && map.ContainsKey(constraint.VariableId ?? "")) t.Constraints.Add(new CyberConstraint { Id = "strategy-" + constraint.Id, VariableKind = "STATE", VariableId = "strategy-" + constraint.VariableId, Name = constraint.Name, Status = "ACTIVE", Minimum = Eq(constraint.Operator, ">=") ? constraint.Threshold : variables[map[constraint.VariableId]].Minimum, Maximum = Eq(constraint.Operator, "<=") ? constraint.Threshold : variables[map[constraint.VariableId]].Maximum, Hard = Eq(constraint.Severity, "HARD"), Penalty = constraint.Penalty }); t.Assumptions.AddRange(model.Assumptions ?? new List<string>()); t.Assumptions.Add("Projected from strategy fingerprint " + CounterfactualStrategyKernel.Fingerprint(model) + "; causal identification and transportability remain unresolved."); t.EvidenceNodeIds.AddRange(model.EvidenceNodeIds ?? new List<string>()); return t;
        }

        private static CyberTwinModel ProjectDiscovery(DiscoveryProtocol protocol)
        {
            List<DiscoveryOutcome> outcomes = (protocol.Outcomes ?? new List<DiscoveryOutcome>()).Where(x => Active(x.Status)).Take(32).ToList(); if (outcomes.Count == 0) return StarterTwin("Discovery twin · " + (protocol.Name ?? "Protocol"), protocol.Charter); CyberTwinModel t = NewProjected("Discovery response twin · " + (protocol.Name ?? "Protocol"), "Linear response-state projection of a preregistered discovery protocol. Design priors do not become observations."); for (int i = 0; i < outcomes.Count; i++) { DiscoveryOutcome o = outcomes[i]; double span = Math.Max(1, Math.Abs(o.RelevantEffect) * 10); t.States.Add(X("outcome-" + o.Id, o.Name, o.Unit, 0, -span, span, Math.Max(1e-8, o.NoiseSigma * o.NoiseSigma), 1)); } t.A = Z(outcomes.Count, outcomes.Count); for (int i = 0; i < outcomes.Count; i++) t.A[i][i] = 0.90;
            List<DiscoveryFactor> factors = (protocol.Factors ?? new List<DiscoveryFactor>()).Where(x => Active(x.Status) && x.Controllable).Take(16).ToList(); if (factors.Count == 0) factors.Add(new DiscoveryFactor { Id = "declared-factor", Name = "Declared factor", Minimum = -1, Maximum = 1, Controllable = true }); t.B = Z(outcomes.Count, factors.Count); for (int j = 0; j < factors.Count; j++) { DiscoveryFactor f = factors[j]; double span = Math.Max(1e-6, f.Maximum - f.Minimum); t.Inputs.Add(U("factor-" + f.Id, f.Name, f.Unit, f.Minimum, f.Maximum, -span * 0.25, span * 0.25, 0.1)); for (int i = 0; i < outcomes.Count; i++) t.B[i][j] = 0.02 * (1 + ((i + j) % 3)); }
            t.C = Z(outcomes.Count, outcomes.Count); t.D = Z(outcomes.Count, factors.Count); for (int i = 0; i < outcomes.Count; i++) { DiscoveryOutcome o = outcomes[i]; t.Outputs.Add(Y("measure-" + o.Id, o.Name, o.Unit, 0, t.States[i].Minimum, t.States[i].Maximum, Math.Max(1e-8, o.NoiseSigma * o.NoiseSigma), 1, 1)); t.C[i][i] = 1; } t.Assumptions.AddRange(protocol.Assumptions ?? new List<string>()); t.Assumptions.Add("Projected from preregistration fingerprint " + ExperimentalDesignKernel.ProtocolFingerprint(protocol) + "; coefficients are placeholders until observations are imported manually."); t.EvidenceNodeIds.AddRange(protocol.EvidenceNodeIds ?? new List<string>()); return t;
        }

