        private static void OpenTwin(Window owner, DeepSystemsContext ctx, WorldIndex index, CyberTwinModel twin)
        {
            if (twin == null) return; Window w = W(owner, "YOMI · " + (twin.Name ?? "DIGITAL TWIN"), 1320, 860); DockPanel root = Shell(twin.Name ?? "DIGITAL TWIN", twin.ToString() + "\n" + (twin.Charter ?? "")); WrapPanel actions = new WrapPanel { Margin = new Thickness(0, 4, 0, 8) };
