        private static void RunFullAnalysis(Window owner, DeepSystemsContext ctx, CyberTwinModel twin)
        {
            string fingerprint = CyberneticsKernel.Fingerprint(twin); CyberTwinAnalysisRecord r = new CyberTwinAnalysisRecord { Id = Id("analysis"), TwinId = twin.Id, CreatedUtc = Now(), TwinFingerprint = fingerprint }; r.Structure = CyberneticsKernel.AnalyzeStructure(twin); r.Lqr = CyberneticsKernel.SynthesizeLqr(twin, 4096, 1e-12); r.Pid = CyberneticsKernel.TunePid(twin, 0, 0, 256); r.Mpc = CyberneticsKernel.SolveMpc(twin, null, 24, 768); r.Reachability = CyberneticsKernel.AnalyzeReachability(twin, 96); r.Robustness = CyberneticsKernel.AnalyzeRobustness(twin, 512, 48, 1337); r.Sensors = CyberneticsKernel.SelectSensors(twin, twin.Outputs.Sum(x => Math.Max(0, x.SensorCost)) * 0.6); r.Audit = CyberneticsKernel.Audit(twin); r.CertificateHash = HashText(fingerprint + "|" + r.CreatedUtc + "|" + Json.Serialize(r.Structure) + "|" + Json.Serialize(r.Lqr) + "|" + Json.Serialize(r.Pid) + "|" + Json.Serialize(r.Mpc) + "|" + Json.Serialize(r.Reachability) + "|" + Json.Serialize(r.Robustness) + "|" + Json.Serialize(r.Sensors) + "|" + String.Join("|", r.Audit.ToArray())); Store.Analyses.Insert(0, r); Save(ctx); AppendLedger(ctx, "ANALYSIS_CERTIFIED", twin.Id, r.Id, fingerprint, r.CertificateHash); OpenRows(owner, "CYBERNETIC ANALYSIS CERTIFICATE", new object[] { r, r.Structure, r.Lqr, r.Pid, r.Mpc, r.Reachability, r.Robustness, r.Sensors }.Concat(r.Audit.Cast<object>()).ToArray(), r.CertificateHash);
        }

        private static void OpenSimulation(Window owner, CyberTwinModel twin) { string raw = Prompt(owner, "SIMULATION CHAMBER", "Horizon (1–512)", "48"); if (raw == null) return; int horizon = Math.Max(1, Math.Min(512, (int)Number(raw, 48))); CyberControllerSynthesis lqr = CyberneticsKernel.SynthesizeLqr(twin, 2048, 1e-11); double[][] controls = Enumerable.Range(0, horizon).Select(k => new double[twin.Inputs.Count]).ToArray(); CyberSimulationResult r = CyberneticsKernel.Simulate(twin, null, controls); r.ControllerKind = "ZERO_INPUT_DECLARED_BASELINE"; OpenRows(owner, "SIMULATION CHAMBER", new object[] { r, lqr }.Concat(r.Steps.Cast<object>()).ToArray(), "Deterministic propagation only · no live plant, process or actuator"); }

