            Window w = W(owner, "YOMI · KALMAN OBSERVATORY", 1200, 780); DockPanel root = Shell("KALMAN OBSERVATORY · " + twin.Name, "Manual declarations only · expected input order: " + String.Join(", ", twin.Inputs.Select(x => x.Id).ToArray()) + " · output order: " + String.Join(", ", twin.Outputs.Select(x => x.Id).ToArray())); ListBox list = List(); Action refresh = delegate { list.ItemsSource = Store.Telemetry.Where(x => Eq(x.TwinId, twin.Id)).OrderByDescending(x => x.Sequence).Take(4096).ToList(); }; refresh(); WrapPanel buttons = new WrapPanel(); buttons.Children.Add(Btn("APPEND FRAME", delegate { string inputRaw = Prompt(w, "MANUAL TELEMETRY", "Input vector, comma-separated", String.Join(",", Enumerable.Repeat("0", twin.Inputs.Count).ToArray())); if (inputRaw == null) return; string outputRaw = Prompt(w, "MANUAL TELEMETRY", "Observed output vector, comma-separated", String.Join(",", twin.Outputs.Select(x => x.Target.ToString("R", CultureInfo.InvariantCulture)).ToArray())); if (outputRaw == null) return; string effective = Prompt(w, "MANUAL TELEMETRY", "Effective time or external sequence label (provenance text)", Now()); if (effective == null) return; AppendTelemetry(ctx, twin, Vector(inputRaw, twin.Inputs.Count), Vector(outputRaw, twin.Outputs.Count), effective); refresh(); })); buttons.Children.Add(Btn("ESTIMATOR TRACE", delegate { List<CyberTelemetryFrame> frames = Store.Telemetry.Where(x => Eq(x.TwinId, twin.Id)).OrderByDescending(x => x.Sequence).Take(4096).OrderBy(x => x.Sequence).ToList(); CyberKalmanResult r = CyberneticsKernel.Estimate(twin, frames.Select(x => x.Input).ToList(), frames.Select(x => x.Output).ToList(), null, 1); OpenRows(w, "KALMAN ESTIMATOR TRACE", new object[] { r }.Concat(r.Steps.Cast<object>()).ToArray(), "Manual telemetry provenance · no sensor acquisition"); })); buttons.Children.Add(Btn("CAPTURE SNAPSHOT", delegate { CaptureSnapshot(w, ctx, twin); })); DockPanel.SetDock(buttons, Dock.Bottom); root.Children.Add(buttons); root.Children.Add(list); w.Content = root; w.Show();
