        private static void AppendTelemetry(DeepSystemsContext ctx, CyberTwinModel twin, double[] input, double[] output, string effective)
        {
            List<CyberTelemetryFrame> prior = Store.Telemetry.Where(x => Eq(x.TwinId, twin.Id)).OrderByDescending(x => x.Sequence).Take(4096).OrderBy(x => x.Sequence).ToList(); List<double[]> controls = prior.Select(x => x.Input).Concat(new[] { input }).ToList(), observations = prior.Select(x => x.Output).Concat(new[] { output }).ToList(); CyberKalmanResult estimate = CyberneticsKernel.Estimate(twin, controls, observations, null, 1); CyberKalmanStep last = estimate.Steps.LastOrDefault(); CyberTelemetryFrame frame = new CyberTelemetryFrame { Id = Id("telemetry"), TwinId = twin.Id, Sequence = prior.Count == 0 ? 1 : prior.Max(x => x.Sequence) + 1, CapturedUtc = Now(), EffectiveTime = Short(effective, 512), SourceKind = "MANUAL_DECLARATION", SourceReference = "operator-entered vector", TwinFingerprint = CyberneticsKernel.Fingerprint(twin), Input = input, Output = output, EstimatedState = last == null ? twin.States.Select(x => x.InitialValue).ToArray() : last.PosteriorState, Innovation = last == null ? new double[twin.Outputs.Count] : last.Innovation, InnovationMahalanobis = last == null ? 0 : last.InnovationMahalanobis }; Store.Telemetry.Insert(0, frame); Save(ctx); AppendLedger(ctx, "TELEMETRY_DECLARED", twin.Id, "frame " + frame.Sequence + " · manual source", frame.TwinFingerprint, "");
        }

        private static void OpenSnapshots(Window owner, DeepSystemsContext ctx, CyberTwinModel twin) { Window w = W(owner, "YOMI · SNAPSHOT VAULT", 1100, 720); DockPanel root = Shell("SNAPSHOT VAULT · " + twin.Name, "Estimator-state certificates bound to manual telemetry and a model fingerprint"); ListBox list = List(); Action refresh = delegate { list.ItemsSource = Store.Snapshots.Where(x => Eq(x.TwinId, twin.Id)).OrderByDescending(x => x.CapturedUtc).ToList(); }; refresh(); Button capture = Btn("CAPTURE", delegate { CaptureSnapshot(w, ctx, twin); refresh(); }); DockPanel.SetDock(capture, Dock.Bottom); root.Children.Add(capture); root.Children.Add(list); w.Content = root; w.Show(); }
        private static void CaptureSnapshot(Window owner, DeepSystemsContext ctx, CyberTwinModel twin) { string name = Prompt(owner, "CAPTURE SNAPSHOT", "Snapshot name", "Estimator snapshot · " + Now()); if (String.IsNullOrWhiteSpace(name)) return; CyberTelemetryFrame frame = Store.Telemetry.Where(x => Eq(x.TwinId, twin.Id)).OrderByDescending(x => x.Sequence).FirstOrDefault(); CyberTwinSnapshot s = new CyberTwinSnapshot { Id = Id("snapshot"), TwinId = twin.Id, Name = Short(name, 240), CapturedUtc = Now(), TwinFingerprint = CyberneticsKernel.Fingerprint(twin), SourceTelemetryFrameId = frame == null ? null : frame.Id, EstimatedState = frame == null ? twin.States.Select(x => x.InitialValue).ToArray() : (double[])frame.EstimatedState.Clone(), LastInput = frame == null ? new double[twin.Inputs.Count] : (double[])frame.Input.Clone(), LastOutput = frame == null ? new double[twin.Outputs.Count] : (double[])frame.Output.Clone() }; s.Assumptions.Add(frame == null ? "No telemetry frame existed; snapshot uses declared initial state." : "State estimate derives exclusively from manually declared telemetry through the model-bound estimator."); s.CertificateHash = HashText(s.Id + "|" + s.TwinId + "|" + s.Name + "|" + s.CapturedUtc + "|" + s.TwinFingerprint + "|" + s.SourceTelemetryFrameId + "|" + Join(s.EstimatedState) + "|" + Join(s.LastInput) + "|" + Join(s.LastOutput) + "|" + String.Join("|", s.Assumptions.ToArray())); Store.Snapshots.Insert(0, s); Save(ctx); AppendLedger(ctx, "SNAPSHOT_CERTIFIED", twin.Id, s.Id, s.TwinFingerprint, s.CertificateHash); }

