        private static void FreezeBaseline(Window owner, DeepSystemsContext ctx, CyberTwinModel twin) { string name = Prompt(owner, "FREEZE TWIN BASELINE", "Immutable baseline name", (twin.Name ?? "Twin") + " · r" + twin.Revision); if (String.IsNullOrWhiteSpace(name)) return; string reason = PromptLarge(owner, "FREEZE TWIN BASELINE", "Reason, boundary and known limitations", "Freeze the declared model for traceable analysis and review. This baseline grants no runtime or actuator authority."); if (reason == null) return; CyberTwinBaseline parent = Store.Baselines.Where(x => Eq(x.TwinId, twin.Id)).OrderByDescending(x => x.FrozenUtc).FirstOrDefault(); CyberTwinBaseline b = new CyberTwinBaseline { Id = Id("baseline"), TwinId = twin.Id, ParentBaselineId = parent == null ? null : parent.Id, Name = Short(name, 240), Status = "FROZEN", FrozenUtc = Now(), Reason = Short(reason, MaxLongText), TwinFingerprint = CyberneticsKernel.Fingerprint(twin), SnapshotJson = Json.Serialize(twin) }; b.BaselineFingerprint = BaselineHash(b); Store.Baselines.Insert(0, b); Save(ctx); AppendLedger(ctx, "BASELINE_FROZEN", twin.Id, b.Id + " · " + b.Name, b.TwinFingerprint, b.BaselineFingerprint); }
        private static string BaselineHash(CyberTwinBaseline b) { return b == null ? HashText("NULL_BASELINE") : HashText("CYBER_BASELINE_V1|" + b.Id + "|" + b.TwinId + "|" + b.ParentBaselineId + "|" + b.Name + "|" + b.Status + "|" + b.FrozenUtc + "|" + b.Reason + "|" + b.TwinFingerprint + "|" + b.SnapshotJson); }

