r(ctx, "DOSSIER_CREATED", twin.Id, d.Id, d.TwinFingerprint, d.AnalysisCertificate); refresh(); })); buttons.Children.Add(Btn("OPEN", delegate { CyberControlDossier d = list.SelectedItem as CyberControlDossier; if (d != null) OpenRows(w, "CONTROL DOSSIER", new object[] { d, "DECISION · " + d.Decision, "AUTHORITY · " + d.AuthorityBoundary }.Concat(d.Assumptions.Select(x => (object)("ASSUMPTION · " + x))).Concat(d.Risks.Select(x => (object)("RISK · " + x))).Concat(d.Dissent.Select(x => (object)("DISSENT · " + x))).ToArray(), d.TwinFingerprint); })); DockPanel.SetDock(buttons, Dock.Bottom); root.Children.Add(buttons); root.Children.Add(list); w.Content = root; w.Show(); }

