        private static void WithTwin(Window owner, DeepSystemsContext ctx, Action<CyberTwinModel> action) { CyberTwinModel twin = ChooseObject(owner, "SELECT DIGITAL TWIN", "Choose an active cybernetic boundary", Store.Twins.Where(x => Active(x.Status)).OrderByDescending(x => x.UpdatedUtc ?? x.CreatedUtc).Cast<object>().ToList()) as CyberTwinModel; if (twin != null && action != null) action(twin); }

        private static void Load(DeepSystemsContext ctx) { lock (Gate) { if (Store != null && Eq(LoadedRoot, ctx.StateRoot)) return; LoadedRoot = ctx.StateRoot; Store = null; string path = StorePath(ctx); if (File.Exists(path)) try { Store = Json.Deserialize<CyberneticTwinStore>(File.ReadAllText(path, Encoding.UTF8)); } catch { PreserveCorrupt(path); } if (Store == null && File.Exists(path + ".previous")) try { Store = Json.Deserialize<CyberneticTwinStore>(File.ReadAllText(path + ".previous", Encoding.UTF8)); } catch { } if (Store == null) Store = new CyberneticTwinStore(); NormalizeStore(); } }
        private static void NormalizeStore() { if (Store == null) Store = new CyberneticTwinStore(); Store.Schema = 1; Store.Twins = Store.Twins ?? new List<CyberTwinModel>(); Store.Analyses = Store.Analyses ?? new List<CyberTwinAnalysisRecord>(); Store.Telemetry = Store.Telemetry ?? new List<CyberTelemetryFrame>(); Store.Snapshots = Store.Snapshots ?? new List<CyberTwinSnapshot>(); Store.Baselines = Store.Baselines ?? new List<CyberTwinBaseline>(); Store.Dossiers = Store.Dossiers ?? new List<CyberControlDossier>(); Store.RecentQuestions = Store.RecentQuestions ?? new List<string>(); foreach (CyberTwinModel t in Store.Twins) { t.States = (t.States ?? new List<CyberStateVariable>()).Take(MaxStates).ToList(); t.Inputs = (t.Inputs ?? new List<CyberControlInput>()).Take(MaxInputs).ToList(); t.Outputs = (t.Outputs ?? new List<CyberMeasuredOutput>()).Take(MaxOutputs).ToList(); t.Constraints = (t.Constraints ?? new List<CyberConstraint>()).Take(MaxConstraints).ToList(); t.FaultSignatures = (t.FaultSignatures ?? new List<CyberFaultSignature>()).Take(MaxFaults).ToList(); t.Assumptions = t.Assumptions ?? new List<string>(); t.EvidenceNodeIds = (t.EvidenceNodeIds ?? new List<string>()).Take(MaxEvidence).ToList(); t.A = t.A ?? new double[0][]; t.B = t.B ?? new double[0][]; t.C = t.C ?? new double[0][]; t.D = t.D ?? new double[0][]; foreach (CyberStateVariable x in t.States) x.EvidenceNodeIds = x.EvidenceNodeIds ?? new List<string>(); foreach (CyberControlInput u in t.Inputs) u.EvidenceNodeIds = u.EvidenceNodeIds ?? new List<string>(); foreach (CyberMeasuredOutput y in t.Outputs) y.EvidenceNodeIds = y.EvidenceNodeIds ?? new List<string>(); foreach (CyberFaultSignature f in t.FaultSignatures) { f.ResidualMeans = f.ResidualMeans ?? new Dictionary<string, double>(StringComparer.OrdinalIgnoreCase); f.ResidualVariances = f.ResidualVariances ?? new Dictionary<string, double>(StringComparer.OrdinalIgnoreCase); f.EvidenceNodeIds = f.EvidenceNodeIds ?? new List<string>(); } } foreach (CyberTwinAnalysisRecord a in Store.Analyses) a.Audit = a.Audit ?? new List<string>(); foreach (CyberTelemetryFrame f in Store.Telemetry) { f.Input = f.Input ?? new double[0]; f.Output = f.Output ?? new double[0]; f.EstimatedState = f.EstimatedState ?? new double[0]; f.Innovation = f.Innovation ?? new double[0]; } foreach (CyberTwinSnapshot s in Store.Snapshots) { s.EstimatedState = s.EstimatedState ?? new double[0]; s.LastInput = s.LastInput ?? new double[0]; s.LastOutput = s.LastOutput ?? new double[0]; s.Assumptions = s.Assumptions ?? new List<string>(); } foreach (CyberControlDossier d in Store.Dossiers) { d.Assumptions = d.Assumptions ?? new List<string>(); d.Risks = d.Risks ?? new List<string>(); d.Dissent = d.Dissent ?? new List<string>(); d.EvidenceNodeIds = d.EvidenceNodeIds ?? new List<string>(); } }
        private static void TrimStore() { NormalizeStore(); Store.Twins = Store.Twins.Take(MaxTwins).ToList(); Store.Analyses = Store.Analyses.Take(MaxAnalyses).ToList(); Store.Telemetry = Store.Telemetry.Take(MaxTelemetry).ToList(); Store.Snapshots = Store.Snapshots.Take(MaxSnapshots).ToList(); Store.Baselines = Store.Baselines.Take(MaxBaselines).ToList(); Store.Dossiers = Store.Dossiers.Take(MaxDossiers).ToList(); Store.RecentQuestions = Store.RecentQuestions.Take(256).ToList(); }
        private static void Save(DeepSystemsContext ctx) { lock (Gate) { TrimStore(); Store.Revision = Math.Max(0, Store.Revision) + 1; Store.UpdatedUtc = Now(); Store.LastCommitId = Id("cyber-commit"); string path = StorePath(ctx); Directory.CreateDirectory(Path.GetDirectoryName(path)); AtomicWrite(path, Json.Serialize(Store)); } }
        private static void AtomicWrite(string path, string text) { string temp = path + ".tmp." + Guid.NewGuid().ToString("N"); File.WriteAllText(temp, text ?? "", new UTF8Encoding(false)); if (File.Exists(path)) { string previous = path + ".previous"; try { File.Replace(temp, path, previous, true); return; } catch { try { File.Copy(path, previous, true); } catch { } } } if (File.Exists(path)) File.Delete(path); File.Move(temp, path); }
        private static void PreserveCorrupt(string path) { try { if (!File.Exists(path)) return; byte[] bytes = File.ReadAllBytes(path); string destination = path + ".corrupt." + HashBytes(bytes).Substring(0, 16) + ".json"; if (!File.Exists(destination)) File.Copy(path, destination); } catch { } }
        private static string StorePath(DeepSystemsContext ctx) { return Path.Combine(ctx.StateRoot, "controller-cybernetic-digital-twins.json"); }
        private static string LedgerPath(DeepSystemsContext ctx) { return Path.Combine(ctx.StateRoot, "controller-cybernetic-digital-twins-ledger.jsonl"); }
        private static void AppendLedger(DeepSystemsContext ctx, string evt, string subject, string detail, string fingerprint, string certificate) { lock (Gate) try { Directory.CreateDirectory(ctx.StateRoot); List<CyberTwinLedgerRecord> prior = ReadLedger(ctx, 16384); CyberTwinLedgerRecord last = prior.OrderByDescending(x => x.Sequence).FirstOrDefault(); CyberTwinLedgerRecord r = new CyberTwinLedgerRecord { Schema = 1, Sequence = last == null ? 1 : last.Sequence + 1, Utc = Now(), Event = Short(evt, 120), Subject = Short(subject, 512), Detail = Short(detail, MaxLongText), CorrelationId = Store == null ? "" : Store.LastCommitId, TwinFingerprint = Short(fingerprint, 128), CertificateHash = Short(certificate, 128), PrevHash = last == null ? new string('0', 64) : last.EntryHash }; r.EntryHash = LedgerHash(r); byte[] bytes = Encoding.UTF8.GetBytes(Json.Serialize(r) + Environment.NewLine); using (FileStream stream = new FileStream(LedgerPath(ctx), FileMode.Append, FileAccess.Write, FileShare.Read, 4096, FileOptions.WriteThrough)) { stream.Write(bytes, 0, bytes.Length); stream.Flush(); } } catch { } }
        private static List<CyberTwinLedgerRecord> ReadLedger(DeepSystemsContext ctx, int cap) { List<CyberTwinLedgerRecord> rows = new List<CyberTwinLedgerRecord>(); if (!File.Exists(LedgerPath(ctx))) return rows; try { foreach (string line in TakeLast(File.ReadLines(LedgerPath(ctx)).Where(x => !String.IsNullOrWhiteSpace(x)), cap)) try { CyberTwinLedgerRecord row = Json.Deserialize<CyberTwinLedgerRecord>(line); if (row != null) rows.Add(row); } catch { } } catch { } return rows; }
        private static string VerifyLedger(List<CyberTwinLedgerRecord> rows) { if (rows == null || rows.Count == 0) return "EMPTY LEDGER"; rows = rows.OrderBy(x => x.Sequence).ToList(); long expected = rows[0].Sequence; string prior = expected == 1 ? new string('0', 64) : rows[0].PrevHash; foreach (CyberTwinLedgerRecord row in rows) { if (row.Sequence != expected) return "CHAIN GAP @ " + expected; if (!Eq(row.PrevHash, prior)) return "PREV HASH MISMATCH @ " + row.Sequence; if (!Eq(row.EntryHash, LedgerHash(row))) return "ENTRY HASH MISMATCH @ " + row.Sequence; expected++; prior = row.EntryHash; } return "CHAIN VERIFIED · " + rows.Count.ToString(CultureInfo.InvariantCulture) + " RECORDS"; }
        private static string LedgerHash(CyberTwinLedgerRecord r) { return HashText(r.Schema + "|" + r.Sequence + "|" + (r.Utc ?? "") + "|" + (r.Event ?? "") + "|" + (r.Subject ?? "") + "|" + (r.Detail ?? "") + "|" + (r.CorrelationId ?? "") + "|" + (r.TwinFingerprint ?? "") + "|" + (r.CertificateHash ?? "") + "|" + (r.PrevHash ?? "")); }

        private static CyberStateVariable X(string id, string name, string unit, double initial, double minimum, double maximum, double processNoise, double weight) { return new CyberStateVariable { Id = id, Name = name, Unit = unit, Status = "ACTIVE", InitialValue = initial, Minimum = minimum, Maximum = maximum, ProcessNoiseVariance = Math.Max(1e-12, processNoise), RegulationWeight = Math.Max(1e-9, weight) }; }
        private static CyberControlInput U(string id, string name, string unit, double minimum, double maximum, double minSlew, double maxSlew, double weight) { return new CyberControlInput { Id = id, Name = name, Unit = unit, Status = "ACTIVE", Minimum = minimum, Maximum = maximum, MinimumSlew = minSlew, MaximumSlew = maxSlew, EffortWeight = Math.Max(1e-9, weight) }; }
        private static CyberMeasuredOutput Y(string id, string name, string unit, double target, double minimum, double maximum, double noise, double weight, double cost) { return new CyberMeasuredOutput { Id = id, Name = name, Unit = unit, Status = "ACTIVE", Target = target, Minimum = minimum, Maximum = maximum, MeasurementNoiseVariance = Math.Max(1e-12, noise), TrackingWeight = Math.Max(1e-9, weight), SensorCost = Math.Max(0, cost) }; }
        private static double[][] M(params double[][] rows) { return rows ?? new double[0][]; }
        private static double[][] Z(int rows, int cols) { double[][] value = new double[Math.Max(0, rows)][]; for (int i = 0; i < value.Length; i++) value[i] = new double[Math.Max(0, cols)]; return value; }
        private static void Touch(CyberTwinModel t) { t.Revision = Math.Max(1, t.Revision) + 1; t.UpdatedUtc = Now(); }
        private static bool Active(string status) { return !Eq(status, "ARCHIVED") && !Eq(status, "DISABLED") && !Eq(status, "RETIRED") && !Eq(status, "REJECTED"); }
        private static bool Eq(string a, string b) { return String.Equals(a ?? "", b ?? "", StringComparison.OrdinalIgnoreCase); }
        private static double Number(string raw, double fallback) { double value; return Double.TryParse(raw, NumberStyles.Float, CultureInfo.InvariantCulture, out value) && !Double.IsNaN(value) && !Double.IsInfinity(value) ? value : fallback; }
        private static double[] Vector(string raw, int count) { string[] parts = (raw ?? "").Split(new[] { ',', ';', ' ', '\t' }, StringSplitOptions.RemoveEmptyEntries); double[] values = new double[Math.Max(0, count)]; for (int i = 0; i < values.Length; i++) values[i] = i < parts.Length ? Number(parts[i], 0) : 0; return values; }
        private static Dictionary<string, double> Pairs(string raw) { Dictionary<string, double> result = new Dictionary<string, double>(StringComparer.OrdinalIgnoreCase); foreach (string part in (raw ?? "").Split(new[] { ',', ';', '\n' }, StringSplitOptions.RemoveEmptyEntries)) { int at = part.IndexOf('='); if (at > 0) result[part.Substring(0, at).Trim()] = Number(part.Substring(at + 1).Trim(), 0); } return result; }
        private static string Join(IEnumerable<double> values) { return String.Join(",", (values ?? Enumerable.Empty<double>()).Select(x => x.ToString("R", CultureInfo.InvariantCulture)).ToArray()); }
        private static string Short(string value, int cap) { value = value ?? ""; cap = Math.Max(1, cap); return value.Length <= cap ? value : value.Substring(0, cap - 1) + "…"; }
        private static string HashText(string value) { return HashBytes(Encoding.UTF8.GetBytes(value ?? "")); }
        private static string HashBytes(byte[] value) { using (SHA256 hash = SHA256.Create()) return BitConverter.ToString(hash.ComputeHash(value ?? new byte[0])).Replace("-", "").ToLowerInvariant(); }
        private static string Id(string prefix) { return prefix + "-" + DateTime.UtcNow.ToString("yyyyMMddHHmmssfff", CultureInfo.InvariantCulture) + "-" + Guid.NewGuid().ToString("N").Substring(0, 8); }
        private static string Now() { return DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture); }
        private static IEnumerable<TValue> TakeLast<TValue>(IEnumerable<TValue> source, int count) { Queue<TValue> q = new Queue<TValue>(); foreach (TValue item in source ?? Enumerable.Empty<TValue>()) { q.Enqueue(item); if (q.Count > count) q.Dequeue(); } foreach (TValue item in q) yield return item; }

        private static void AddGrid(Grid grid, UIElement child, int row, int column) { Grid.SetRow(child, row); Grid.SetColumn(child, column); grid.Children.Add(child); }
        private static Window W(Window owner, string title, double width, double height) { return new Window { Title = title, Width = width, Height = height, MinWidth = Math.Min(width, 820), MinHeight = Math.Min(height, 560), Background = Bg, Foreground = Text, WindowStartupLocation = WindowStartupLocation.CenterOwner, Owner = owner, FontFamily = new FontFamily("Segoe UI") }; }
        private static DockPanel Shell(string title, string subtitle) { DockPanel root = new DockPanel { Margin = new Thickness(16) }; StackPanel head = new StackPanel { Margin = new Thickness(0, 0, 0, 10) }; head.Children.Add(T(title, 24, Text, FontWeights.Bold)); head.Children.Add(T(subtitle, 12, Muted, FontWeights.Normal)); DockPanel.SetDock(head, Dock.Top); root.Children.Add(head); return root; }
        private static TextBlock T(string value, double size, Brush foreground, FontWeight weight) { return new TextBlock { Text = value ?? "", FontSize = size, Foreground = foreground, FontWeight = weight, TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 2, 0, 2) }; }
        private static Button Btn(string label, RoutedEventHandler click) { Button button = new Button { Content = label, Margin = new Thickness(0, 0, 8, 8), Padding = new Thickness(12, 7, 12, 7), Background = Raised, Foreground = Text, BorderBrush = Border, BorderThickness = new Thickness(1), MinWidth = 112 }; if (click != null) button.Click += click; return button; }
        private static ListBox List() { return new ListBox { Background = Surface, Foreground = Text, BorderBrush = Border, BorderThickness = new Thickness(1), Margin = new Thickness(0, 6, 6, 0), Padding = new Thickness(5), FontFamily = new FontFamily("Cascadia Mono, Consolas") }; }
        private static void Portal(Panel parent, string badge, string title, string description, Action open) { Button button = new Button { Width = 360, Height = 120, Margin = new Thickness(0, 0, 10, 10), Padding = new Thickness(12), Background = Surface, Foreground = Text, BorderBrush = Border, BorderThickness = new Thickness(1), HorizontalContentAlignment = HorizontalAlignment.Stretch }; StackPanel content = new StackPanel(); content.Children.Add(T(badge + "   " + title, 14, Accent, FontWeights.Bold)); content.Children.Add(T(description, 11.5, Muted, FontWeights.Normal)); button.Content = content; button.Click += delegate { if (open != null) open(); }; parent.Children.Add(button); }
        private static Brush B(string hex) { return new SolidColorBrush((Color)ColorConverter.ConvertFromString(hex)); }
        private static string Prompt(Window owner, string title, string label, string initial) { Window w = W(owner, "YOMI · " + title, 680, 290); DockPanel root = new DockPanel { Margin = new Thickness(16) }; TextBlock caption = T(label, 12, Muted, FontWeights.Normal); DockPanel.SetDock(caption, Dock.Top); root.Children.Add(caption); TextBox editor = new TextBox { Text = initial ?? "", MaxLength = MaxShortText, Margin = new Thickness(0, 8, 0, 10), Background = Surface, Foreground = Text, BorderBrush = Border, Padding = new Thickness(8) }; DockPanel.SetDock(editor, Dock.Top); root.Children.Add(editor); WrapPanel buttons = new WrapPanel { HorizontalAlignment = HorizontalAlignment.Right }; string result = null; buttons.Children.Add(Btn("OK", delegate { result = editor.Text; w.DialogResult = true; })); buttons.Children.Add(Btn("CANCEL", delegate { w.DialogResult = false; })); root.Children.Add(buttons); w.Content = root; bool? accepted = w.ShowDialog(); return accepted == true ? result : null; }
        private static string PromptLarge(Window owner, string title, string label, string initial) { Window w = W(owner, "YOMI · " + title, 800, 560); DockPanel root = new DockPanel { Margin = new Thickness(16) }; TextBlock caption = T(label, 12, Muted, FontWeights.Normal); DockPanel.SetDock(caption, Dock.Top); root.Children.Add(caption); TextBox editor = new TextBox { Text = initial ?? "", MaxLength = MaxLongText, AcceptsReturn = true, AcceptsTab = true, TextWrapping = TextWrapping.Wrap, VerticalScrollBarVisibility = ScrollBarVisibility.Auto, Margin = new Thickness(0, 8, 0, 0), Background = Surface, Foreground = Text, BorderBrush = Border, Padding = new Thickness(10), FontFamily = new FontFamily("Cascadia Mono, Consolas") }; WrapPanel buttons = new WrapPanel { HorizontalAlignment = HorizontalAlignment.Right, Margin = new Thickness(0, 10, 0, 0) }; string result = null; buttons.Children.Add(Btn("SAVE", delegate { result = editor.Text; w.DialogResult = true; })); buttons.Children.Add(Btn("CANCEL", delegate { w.DialogResult = false; })); DockPanel.SetDock(buttons, Dock.Bottom); root.Children.Add(buttons); root.Children.Add(editor); w.Content = root; bool? accepted = w.ShowDialog(); return accepted == true ? result : null; }
        private static object ChooseObject(Window owner, string title, string label, IList<object> choices) { Window w = W(owner, "YOMI · " + title, 720, 500); DockPanel root = new DockPanel { Margin = new Thickness(16) }; TextBlock caption = T(label, 12, Muted, FontWeights.Normal); DockPanel.SetDock(caption, Dock.Top); root.Children.Add(caption); ListBox list = List(); list.ItemsSource = choices ?? new List<object>(); if (list.Items.Count > 0) list.SelectedIndex = 0; WrapPanel buttons = new WrapPanel { HorizontalAlignment = HorizontalAlignment.Right, Margin = new Thickness(0, 10, 0, 0) }; object result = null; buttons.Children.Add(Btn("SELECT", delegate { result = list.SelectedItem; w.DialogResult = true; })); buttons.Children.Add(Btn("CANCEL", delegate { w.DialogResult = false; })); list.MouseDoubleClick += delegate { result = list.SelectedItem; if (result != null) w.DialogResult = true; }; DockPanel.SetDock(buttons, Dock.Bottom); root.Children.Add(buttons); root.Children.Add(list); w.Content = root; bool? accepted = w.ShowDialog(); return accepted == true ? result : null; }
        private static void OpenRows(Window owner, string title, object value, string subtitle) { IEnumerable<object> rows = value as IEnumerable<object>; OpenRows(owner, title, rows == null ? new object[] { value } : rows.ToArray(), subtitle); }
        private static void OpenRows(Window owner, string title, IList<object> rows, string subtitle) { Window w = W(owner, "YOMI · " + title, 1220, 820); DockPanel root = Shell(title, subtitle); ListBox list = List(); list.ItemsSource = rows ?? new List<object>(); root.Children.Add(list); w.Content = root; w.Show(); }
    }
